              const m = T.body.getMass(), v0 = b.getLinearVelocity(), k2 = clamp(b.getMass() / m, 0.75, 1.3) * Math.min(1, c.pw);
              T.body.setLinearVelocity(V(v0.x, v0.y)); T.body.applyLinearImpulse(V(-fwd.x * m * 3.4 * k2, -fwd.y * m * 3.4 * k2), T.body.getWorldCenter(), true);
